home=function(){return `<div class="page"><section class="hero"><div class="hero-card"><span class="eyebrow">GENERATIVE AI PRACTICAL WORKSHOP</span><h1>10분 만에 보고서 초안 잡는,<br><em>생성형 AI 활용법</em></h1><p>보고서 작성 형식을 외우는 수업이 아니라, 생성형 AI의 원리와 한계를 이해하고 질문·파일·이미지·표를 업무 결과물로 바꾸는 실습형 과정입니다. 보고서는 배운 AI 기술을 통합하는 최종 사례로 활용합니다.</p><div class="actions"><button class="button orange" data-route="lesson1">AI 활용 과정 시작</button><button class="button secondary" data-route="builder">AI 종합실습 도구</button></div></div><aside class="hero-card hero-side"><span class="eyebrow">오늘의 도착점</span><h2>교육 후 직접 할 수 있어야 합니다</h2><div class="goal"><b>01</b><span>생성형 AI의 강점·한계를 이해하고 제대로 질문하기</span></div><div class="goal"><b>02</b><span>텍스트·파일·이미지·표를 다양한 업무 결과물로 변환하기</span></div><div class="goal"><b>03</b><span>AI 결과를 검증하고 보고서·메일·회의·기획 업무로 확장하기</span></div></aside></section><section class="card" style="margin-bottom:22px"><span class="eyebrow">240-MINUTE JOURNEY</span><h2>4시간 학습 여정</h2><div class="timed-activity"><div><b>0:00–0:30 · 30분</b><span>PART 1 · AI 이해</span></div><div><b>0:30–1:10 · 40분</b><span>PART 2 · AI 대화법</span></div><div><b>1:10–1:20 · 10분</b><span>휴식</span></div><div><b>1:20–2:10 · 50분</b><span>PART 3 · 업무 변환</span></div><div><b>2:10–3:05 · 55분</b><span>PART 4 · 보고서 종합실습</span></div><div><b>3:05–3:15 · 10분</b><span>휴식</span></div><div><b>3:15–4:00 · 45분</b><span>PART 5 · NotebookLM·검증·확장</span></div></div><div class="callout"><b>총 240분</b><br>설명 65분 · 시연과 따라 하기 55분 · 직접 실습과 검토 100분 · 휴식 20분으로 운영합니다.</div></section><div class="route-grid">${lessons.map((x,i)=>`<article class="route-card"><small>PART ${String(i+1).padStart(2,'0')} · ${x.time}</small><b>${x.title}</b><p>${x.desc}</p><button class="button ghost" data-route="${x.id}">열기</button></article>`).join('')}</div><div class="callout" style="margin-top:22px"><b>이번 강의에서 배우는 것</b><br>생성형 AI의 핵심 기능을 익히고, 실제 업무자료를 보고서 초안으로 바꾼 뒤 정확성을 검토하는 과정까지 실습합니다.</div></div>`};

courseSteps.lesson1=[
 {time:'6분',title:'검색과 생성은 다르다',body:`<div class="compare"><div><span class="tag">검색</span><h2>있는 정보를 찾기</h2><p>출처·날짜·정확한 사실 확인에 강합니다.</p></div><div><span class="tag">생성형 AI</span><h2>가능한 답을 만들기</h2><p>정리·변환·초안·아이디어에 강하지만 그럴듯하게 틀릴 수 있습니다.</p></div></div><div class="callout"><b>쉬운 비유:</b> 검색은 서가에서 책을 찾는 사서, 생성형 AI는 읽은 패턴으로 새 문장을 만드는 작가에 가깝습니다.</div>`},
 {time:'8분',title:'같은 질문, 다른 결과',body:`<div class="prompt-levels ai-question-tabs" role="tablist" aria-label="비교할 질문 선택"><button class="prompt-level active" data-ai-question="1" role="tab" aria-selected="true"><b>질문 1</b><small>회의 정리해줘</small></button><button class="prompt-level" data-ai-question="2" role="tab" aria-selected="false"><b>질문 2</b><small>결정·담당·기한 추출</small></button><button class="prompt-level" data-ai-question="3" role="tab" aria-selected="false"><b>질문 3</b><small>빠진 정보부터 질문</small></button></div><section class="ai-question-detail" id="ai-question-detail" aria-live="polite"></section><div class="callout"><b>비교 포인트</b><br>AI의 성능만큼 중요한 것이 사람이 제공한 맥락과 결과 기준입니다. 같은 회의 메모라도 질문이 구체적일수록 결과가 실행 가능한 형태로 바뀝니다.</div>`},
 {time:'10분',title:'AI가 잘하는 6가지',body:`<div class="six-grid">${[['요약','긴 내용을 짧게'],['분류','비슷한 항목 묶기'],['변환','메모를 표·메일로'],['초안','빈 화면 빠르게 채우기'],['비교','차이·공통점 찾기'],['질문','누락·예상질문 찾기']].map((x,i)=>`<article class="formula-card"><span>${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></article>`).join('')}</div>`},
 {time:'10분',title:'AI가 위험한 4가지',body:`<div class="peer-review"><div><b>환각</b><p>없는 사실을 자연스럽게 만듦</p></div><div><b>최신성</b><p>현재 정보가 아닐 수 있음</p></div><div><b>맥락 부족</b><p>회사 사정을 모름</p></div><div><b>책임 없음</b><p>결정 결과를 책임지지 않음</p></div></div><div class="prompt-box bad">“우리 회사 규정상 반드시 이렇게 해야 합니다.” — 규정 파일을 주지 않았다면 그대로 믿으면 안 됩니다.</div>`},
 {time:'6분',title:'내 업무와 AI 연결',body:`<div class="sort-quiz"><h2>업무를 AI 역할에 연결해 보세요</h2>${[['긴 공지 핵심만 보기','요약'],['회의 후 실행항목 만들기','추출'],['현장사진 설명문 만들기','이미지 이해'],['메모를 여러 문서로 바꾸기','변환']].map((x,i)=>`<button class="prompt-preview-trigger" data-reveal="work-prompt-${i}" data-open-label="${x[0]} 프롬프트 보기" data-close-label="프롬프트 닫기" aria-expanded="false"><span>${i+1}</span>${x[0]} → ${x[1]}</button><section id="work-prompt-${i}" class="full-prompt-panel" hidden><div class="prompt-box good">${x[0]} 업무를 생성형 AI로 처리하는 안전한 절차와 프롬프트를 만들어줘.</div><button class="button orange copy-module-text" data-copy="${x[0]} 업무를 생성형 AI로 처리하는 안전한 절차와 프롬프트를 만들어줘.">이 프롬프트 복사</button></section>`).join('')}</div>`}
];

lesson2Steps.splice(0,lesson2Steps.length,
 {time:'5분',title:'AI 대화는 설계다',body:`<div class="lesson-two-lead"><span class="tag">PROMPT ≠ 주문</span><h2>좋은 프롬프트는 긴 주문이 아니라 좋은 업무 설명입니다</h2><p>한 번에 완벽한 답을 받으려 하지 말고 질문–응답–수정의 순환을 만듭니다.</p></div><div class="report-spine"><div><span>1</span><b>맥락</b><small>어떤 상황?</small></div><div><span>2</span><b>목적</b><small>무엇을 위해?</small></div><div><span>3</span><b>자료</b><small>무엇을 근거로?</small></div><div><span>4</span><b>형식</b><small>어떤 결과?</small></div><div><span>5</span><b>검증</b><small>어떻게 확인?</small></div></div><div class="callout"><b>쉽게 말하면</b><br><b>맥락과 목적</b>은 지금 어떤 상황이고 이 결과로 무엇을 바꾸려는지 알려주는 것입니다.<br><b>자료</b>는 어디까지를 사실로 사용할지 정하고, 자료에 없는 내용은 [확인 필요]로 남기는 것입니다.<br><b>형식과 검증</b>은 독자가 해야 할 행동에 맞춰 결과물의 모양을 정한 뒤 원자료와 다시 확인하는 것입니다.</div>`},
 {time:'9분',title:'1·2 맥락과 목적',body:`<div class="compare"><div><span class="tag">맥락 없음</span><div class="prompt-box bad">안내문 써줘.</div></div><div><span class="tag">맥락·목적 있음</span><div class="prompt-box good">생산현장 작업자에게 내일부터 바뀌는 위생도구 보관 위치를 알려 혼선을 줄이는 안내문을 작성해줘.</div></div></div><div class="facilitator"><b>실습</b><span>내 업무에 ‘누가·왜·어떤 상황에서’를 한 문장으로 추가합니다.</span></div>`},
 {time:'8분',title:'3 자료의 경계',body:`<div class="callout">많은 자료보다 어떤 자료만 믿어야 하는지 알려주는 것이 중요합니다. 아래에서 실행 지시와 자료가 합쳐진 전체 프롬프트를 확인할 수 있습니다.</div><button class="button secondary prompt-preview-trigger" data-reveal="source-boundary-prompt" data-open-label="자료 포함 전체 프롬프트 보기" data-close-label="전체 프롬프트 닫기" aria-expanded="false">자료 포함 전체 프롬프트 보기</button><section id="source-boundary-prompt" class="full-prompt-panel" hidden><div class="prompt-box good">아래 제공한 내용만 근거로 사용해 ① 확인된 사실 ② 실시한 조치 ③ 예정된 후속조치 ④ 추가 확인이 필요한 항목으로 정리하세요. 자료에 없는 사실·수치·원인은 추측하지 말고 [확인 필요]로 표시하세요.\n\n[제공 자료]\n9월 25일 14시 포장구역 점검 중 세척도구 1개가 작업대 하단에서 발견됐다. 해당 도구는 즉시 회수해 세척·소독한 뒤 지정 보관함으로 옮겼다. 작업자 6명에게 보관 기준을 다시 안내했으며 9월 26일 재점검 예정이다.</div><button class="button orange copy-module-text" data-copy="아래 제공한 내용만 근거로 사용해 ① 확인된 사실 ② 실시한 조치 ③ 예정된 후속조치 ④ 추가 확인이 필요한 항목으로 정리하세요. 자료에 없는 사실·수치·원인은 추측하지 말고 [확인 필요]로 표시하세요.\n\n[제공 자료]\n9월 25일 14시 포장구역 점검 중 세척도구 1개가 작업대 하단에서 발견됐다. 해당 도구는 즉시 회수해 세척·소독한 뒤 지정 보관함으로 옮겼다. 작업자 6명에게 보관 기준을 다시 안내했으며 9월 26일 재점검 예정이다.">전체 프롬프트 복사</button></section>`},
 {time:'8분',title:'4 결과 형식',body:`<div class="six-grid">${[['요약','3줄 핵심'],['표','항목별 비교'],['메일','제목·본문·요청'],['체크리스트','행동 중심'],['보고서','목차형 초안'],['질문','확인할 3가지']].map((x,i)=>`<article class="formula-card"><span>${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></article>`).join('')}</div>`},
 {time:'8분',title:'5 AI에게 검증시키기',body:`<div class="compare"><div><span class="tag">막연한 요청</span><div class="prompt-box bad">더 전문적으로 고쳐줘.</div></div><div><span class="tag">검증 요청</span><div class="prompt-box good">원자료와 초안을 대조해 근거 없는 내용·빠진 정보·모호한 표현을 먼저 표로 진단해줘. 아직 수정본은 쓰지 마.</div></div></div><div class="review-materials"><section><span class="tag">원자료</span><h3>확인된 사실</h3><p>9월 24일 포장 2라인 라벨프린터가 정지했다. 재부팅 후 작동했으며 출하 준비가 20분 지연되고 라벨 46장을 재출력했다. 최근 5일간 세 번째 발생이며 원인은 아직 확인되지 않았다.</p></section><section class="draft-with-errors"><span class="tag">일부러 오류를 넣은 AI 초안</span><h3>검토할 문장</h3><p><mark>노후 센서 고장으로</mark> 라벨프린터가 정지해 출하가 20분 지연됐다. 라벨 46장을 재출력했으며 <mark>다음 달까지 새 장비로 교체하기로 했다.</mark></p><small>표시된 두 내용은 원자료에서 확인되지 않습니다.</small></section></div><div class="callout"><b>확인할 것</b><br>원자료에 있는 사실과 AI가 새로 만들어낸 원인·결정을 구분한 뒤, 바로 고치기 전에 근거 여부부터 진단합니다.</div><button class="button secondary prompt-reveal" data-reveal="full-review-prompt" aria-expanded="false">원자료·AI 초안·검토 지시 전체 보기</button><section id="full-review-prompt" class="full-prompt-panel" hidden><div class="prompt-box good">아래 원자료와 AI 초안을 대조하세요. 초안을 바로 고치지 말고 각 문장을 ① 원자료로 확인됨 ② 근거 없음 ③ 추가 확인 필요로 판정한 표를 만드세요. 빠진 정보와 모호한 표현도 별도로 적으세요.

[원자료]
9월 24일 포장 2라인 라벨프린터가 정지했다. 재부팅 후 작동했으며 출하 준비가 20분 지연되고 라벨 46장을 재출력했다. 최근 5일간 세 번째 발생이며 원인은 아직 확인되지 않았다.

[AI 초안]
노후 센서 고장으로 라벨프린터가 정지해 출하가 20분 지연됐다. 라벨 46장을 재출력했으며 다음 달까지 새 장비로 교체하기로 했다.</div><button class="button orange copy-module-text" data-copy="아래 원자료와 AI 초안을 대조하세요. 초안을 바로 고치지 말고 각 문장을 ① 원자료로 확인됨 ② 근거 없음 ③ 추가 확인 필요로 판정한 표를 만드세요. 빠진 정보와 모호한 표현도 별도로 적으세요.\n\n[원자료]\n9월 24일 포장 2라인 라벨프린터가 정지했다. 재부팅 후 작동했으며 출하 준비가 20분 지연되고 라벨 46장을 재출력했다. 최근 5일간 세 번째 발생이며 원인은 아직 확인되지 않았다.\n\n[AI 초안]\n노후 센서 고장으로 라벨프린터가 정지해 출하가 20분 지연됐다. 라벨 46장을 재출력했으며 다음 달까지 새 장비로 교체하기로 했다.">전체 프롬프트 복사</button></section>`},
 {time:'7분',title:'이어 묻기의 힘',body:`<div class="timed-activity"><div><b>1차</b><span>초안 생성</span></div><div><b>2차</b><span>빠진 정보 질문</span></div><div><b>3차</b><span>독자 관점 비판</span></div><div><b>4차</b><span>최종 수정</span></div></div><div class="facilitator"><b>연습</b><span>첫 답변을 끝으로 보지 않고 최소 두 번 이어 묻습니다.</span></div>`},
 {time:'5분',title:'프롬프트에서 빠진 요소 찾기',body:`<div class="quiz"><h2>다음 요청에서 빠진 요소는?</h2><div class="prompt-box">아래 회의 메모만 사용해 팀장에게 전달할 결정사항 표를 만들어줘.</div><div class="quiz-options"><button data-quiz="wrong">맥락·자료·형식</button><button data-quiz="correct" data-answer="정답입니다. 근거 없는 내용과 누락을 점검할 검증 기준이 빠졌습니다.">검증 기준</button><button data-quiz="wrong">목적·독자</button></div><div id="quiz-feedback" class="quiz-feedback">정답을 선택하세요.</div></div>`}
);

courseSteps.lesson3=[
 {time:'8분',title:'하나의 자료, 다섯 결과',body:`<div class="report-spine"><div><span>1</span><b>요약</b><small>핵심 3줄</small></div><div><span>2</span><b>표</b><small>사실 분류</small></div><div><span>3</span><b>메일</b><small>공유·요청</small></div><div><span>4</span><b>체크</b><small>실행 항목</small></div><div><span>5</span><b>보고</b><small>의사결정</small></div></div><div class="callout"><b>예를 들어</b><br>같은 회의 메모도 팀장에게는 핵심 요약과 보고서로, 담당자에게는 요청 메일과 실행 체크리스트로 바꿀 수 있습니다.<br>형식이 달라져도 날짜·수량·확정 여부 같은 핵심 사실은 달라지면 안 됩니다.</div>`},
 {time:'12분',title:'긴 글·파일 읽히기',body:`<div class="three-rules"><div><span>1</span><h3>먼저 구조</h3><p>문서의 목차와 핵심 주제를 찾습니다.</p></div><div><span>2</span><h3>근거 표시</h3><p>답의 근거 위치를 함께 요구합니다.</p></div><div><span>3</span><h3>추가 질문</h3><p>요약 후 필요한 부분을 좁혀 묻습니다.</p></div></div><section class="download-practice"><div><span class="tag">실습 첨부문서</span><h3>생산현장 위생점검 개선 운영계획</h3><p>가상의 교육용 문서입니다. 다운로드한 PDF를 Gemini에 첨부한 뒤 아래 프롬프트로 구조·근거·실행항목을 확인합니다.</p><small>PDF · 2쪽 내외 · 개인정보 및 실제 회사정보 없음</small></div><a class="button orange" href="assets/haedream-hygiene-improvement-plan.pdf" download="생산현장_위생점검_개선_운영계획_교육용.pdf">실습 문서 다운로드</a></section><div class="practice-flow"><span><b>1</b> 문서 다운로드</span><span><b>2</b> Gemini에 첨부</span><span><b>3</b> 프롬프트 입력</span><span><b>4</b> 근거 대조</span></div><div class="prompt-box good">첨부 문서를 읽고 ① 문서 목적 ② 핵심 내용 ③ 실행항목(담당·기한 포함) ④ 확인 필요사항을 구분해 정리해줘. 각 답변 옆에는 근거가 있는 문서의 절 제목이나 표의 행을 표시하고, 문서에 없는 내용은 추측하지 말고 [확인 필요]로 표시해줘.</div><button class="button secondary copy-module-text" data-copy="첨부 문서를 읽고 ① 문서 목적 ② 핵심 내용 ③ 실행항목(담당·기한 포함) ④ 확인 필요사항을 구분해 정리해줘. 각 답변 옆에는 근거가 있는 문서의 절 제목이나 표의 행을 표시하고, 문서에 없는 내용은 추측하지 말고 [확인 필요]로 표시해줘.">분석 프롬프트 복사</button>`},
 {time:'10분',title:'이미지에서 정보 찾기',body:`<section class="image-practice"><div class="image-practice-preview"><span class="tag">실습 이미지</span><img src="assets/training-packing-area-inspection.png" alt="상자 세 개, 클립보드, 안전 콘과 주의 표지판이 보이는 가상의 포장 작업 구역"><div class="image-practice-actions"><a class="button orange" href="assets/training-packing-area-inspection.png" download="생성형AI_이미지분석_실습사진.png">실습 사진 다운로드</a><small>가상의 교육용 이미지 · 개인정보 및 실제 회사정보 없음</small></div></div><div class="image-practice-guide"><span class="tag">질문</span><h3>보이는 사실과 추정을 분리합니다</h3><div class="prompt-box good">첨부한 사진을 관찰해 ① 직접 확인되는 사실 ② 사진만으로는 확정할 수 없는 추정 ③ 추가 확인이 필요한 사항으로 나눠 정리해줘. 사람·물체·수량·위치·눈에 보이는 상태만 사실로 기록하고, 원인·의도·위험도는 근거 없이 단정하지 마. 마지막에 현장 담당자에게 확인할 질문 3개를 제안해줘.</div><button class="button secondary copy-module-text" data-copy="첨부한 사진을 관찰해 ① 직접 확인되는 사실 ② 사진만으로는 확정할 수 없는 추정 ③ 추가 확인이 필요한 사항으로 나눠 정리해줘. 사람·물체·수량·위치·눈에 보이는 상태만 사실로 기록하고, 원인·의도·위험도는 근거 없이 단정하지 마. 마지막에 현장 담당자에게 확인할 질문 3개를 제안해줘.">분석 프롬프트 복사</button></div></section><div class="practice-flow"><span><b>1</b> 사진 다운로드</span><span><b>2</b> Gemini에 첨부</span><span><b>3</b> 프롬프트 입력</span><span><b>4</b> 사실·추정 대조</span></div><div class="callout">사진 속 개인정보·설비정보·문서 내용도 보안대상일 수 있습니다. 실제 현장사진은 회사의 업로드 허용 기준을 먼저 확인하세요.</div>`},
 {time:'12분',title:'표와 비교 분석',body:`<div class="timed-activity"><div><b>추출</b><span>날짜·수량·상태</span></div><div><b>정리</b><span>표로 구조화</span></div><div><b>비교</b><span>차이·추세</span></div><div><b>질문</b><span>추가 확인</span></div></div><div class="prompt-box"><b>분석할 교육용 기록</b>\n9/20 포장 2라인 라벨프린터 정지, 18분 지연, 라벨 38장 재출력, 재부팅 후 작동.\n9/22 포장 2라인 같은 장비 정지, 12분 지연, 라벨 21장 재출력, 케이블 재연결 후 작동.\n9/24 포장 2라인 같은 장비 정지, 20분 지연, 라벨 46장 재출력, 재부팅 후 작동. 원인은 세 건 모두 미확인.</div><button class="button secondary prompt-preview-trigger" data-reveal="table-analysis-prompt" data-open-label="기록 포함 분석 프롬프트 보기" data-close-label="전체 프롬프트 닫기" aria-expanded="false">기록 포함 분석 프롬프트 보기</button><section id="table-analysis-prompt" class="full-prompt-panel" hidden><div class="prompt-box good">아래 기록에서 날짜·장비·업무 지연시간·재출력 수량·임시조치·원인 확인 여부를 추출해 표로 만드세요. 그다음 반복되는 패턴과 추가 확인 질문을 구분해 제시하세요. 기록에 없는 원인은 추측하지 마세요.\n\n[기록]\n9/20 포장 2라인 라벨프린터 정지, 18분 지연, 라벨 38장 재출력, 재부팅 후 작동.\n9/22 포장 2라인 같은 장비 정지, 12분 지연, 라벨 21장 재출력, 케이블 재연결 후 작동.\n9/24 포장 2라인 같은 장비 정지, 20분 지연, 라벨 46장 재출력, 재부팅 후 작동. 원인은 세 건 모두 미확인.</div><button class="button orange copy-module-text" data-copy="아래 기록에서 날짜·장비·업무 지연시간·재출력 수량·임시조치·원인 확인 여부를 추출해 표로 만드세요. 그다음 반복되는 패턴과 추가 확인 질문을 구분해 제시하세요. 기록에 없는 원인은 추측하지 마세요.\n\n[기록]\n9/20 포장 2라인 라벨프린터 정지, 18분 지연, 라벨 38장 재출력, 재부팅 후 작동.\n9/22 포장 2라인 같은 장비 정지, 12분 지연, 라벨 21장 재출력, 케이블 재연결 후 작동.\n9/24 포장 2라인 같은 장비 정지, 20분 지연, 라벨 46장 재출력, 재부팅 후 작동. 원인은 세 건 모두 미확인.">전체 프롬프트 복사</button></section>`},
 {time:'12분',title:'업무자료로 보고서 초안 만들기',body:`<div class="callout"><b>보고서 작성 실습</b><br>앞에서 익힌 자료 읽기와 질문 방법을 사용해 아래 네 가지 업무 중 하나의 보고서 초안을 만듭니다.</div><div class="scenario-tabs">${Object.entries(scenarios).map(([k,v],i)=>`<button class="scenario-open ${i===0?'active':''}" data-scenario="${k}">${v.name}</button>`).join('')}</div><div id="scenario-view"></div><div class="callout"><b>첫 결과물에 A 또는 B 중 하나를 이어서 요청합니다.</b><br>작성기 프롬프트로 첫 결과물 1개를 만든 뒤, 같은 Gemini 대화창에 아래 A 또는 B 프롬프트 하나만 입력해 다른 형식의 결과물 1개를 만드세요.</div><div class="timed-activity"><div><b>1</b><span>사례 선택 후 작성기 열기</span></div><div><b>2</b><span>작성기 프롬프트로 첫 결과물 생성</span></div><div><b>3</b><span>같은 창에 A 또는 B 하나만 입력</span></div><div><b>4</b><span>첫 결과물과 새 결과물 비교·수정</span></div></div><div class="compare"><section><span class="tag">선택 A · 둘 중 하나만</span><h3>실행 체크리스트로 바꾸기</h3><p>처음 만든 문서와 실제 행동에 쓰는 체크리스트의 차이를 비교합니다.</p><div class="prompt-box good">방금 만든 첫 결과물을 담당자가 바로 실행할 수 있는 체크리스트로 바꿔줘. 첫 결과물과 사실·수치·일정은 동일하게 유지하고, 원자료에 없는 내용은 [확인 필요]로 표시해줘. 마지막에 첫 결과물과 체크리스트의 적합한 사용 상황, 장점, 한계를 비교표로 정리해줘.</div><button class="button secondary copy-module-text" data-copy="방금 만든 첫 결과물을 담당자가 바로 실행할 수 있는 체크리스트로 바꿔줘. 첫 결과물과 사실·수치·일정은 동일하게 유지하고, 원자료에 없는 내용은 [확인 필요]로 표시해줘. 마지막에 첫 결과물과 체크리스트의 적합한 사용 상황, 장점, 한계를 비교표로 정리해줘.">선택 A 프롬프트 복사</button></section><section><span class="tag">선택 B · 둘 중 하나만</span><h3>관련 부서 메일로 바꾸기</h3><p>처음 만든 문서와 상대에게 전달하는 업무 메일의 차이를 비교합니다.</p><div class="prompt-box good">방금 만든 첫 결과물을 관련 부서에 상황과 협조 요청을 전달하는 업무 메일로 바꿔줘. 첫 결과물과 사실·수치·일정은 동일하게 유지하고, 원자료에 없는 내용은 [확인 필요]로 표시해줘. 마지막에 첫 결과물과 업무 메일의 적합한 사용 상황, 장점, 한계를 비교표로 정리해줘.</div><button class="button secondary copy-module-text" data-copy="방금 만든 첫 결과물을 관련 부서에 상황과 협조 요청을 전달하는 업무 메일로 바꿔줘. 첫 결과물과 사실·수치·일정은 동일하게 유지하고, 원자료에 없는 내용은 [확인 필요]로 표시해줘. 마지막에 첫 결과물과 업무 메일의 적합한 사용 상황, 장점, 한계를 비교표로 정리해줘.">선택 B 프롬프트 복사</button></section></div><div class="facilitator"><b>두 결과물이란?</b><span>① 작성기 프롬프트로 만든 첫 결과물 1개와 ② A 또는 B로 형식을 바꾼 새 결과물 1개입니다.</span></div><div class="facilitator"><b>비교할 네 가지</b><span>① 누가 사용하는가 ② 바로 행동할 수 있는가 ③ 핵심 사실이 빠지지 않았는가 ④ 원자료에 없는 내용이 생기지 않았는가</span></div><div class="callout"><b>완료 결과</b><br>첫 결과물 1개 + A 또는 B로 만든 새 결과물 1개 + 형식별 유용성 비교표 + 사람이 수정한 부분 1개를 남기면 활동 완료입니다.</div>`},
 {time:'6분',title:'변환 결과 비교·공유',body:`<div class="presentation-guide"><h2>개인·짝·조별 결과를 60초로 공유합니다</h2><ol><li>어떤 원자료와 두 형식을 선택했는가?</li><li>두 형식은 각각 누구에게, 언제 더 유용했는가?</li><li>같은 사실이 두 결과물에서 다르게 변하거나 빠지지 않았는가?</li><li>AI가 잘한 부분과 사람이 수정한 부분은 무엇인가?</li></ol></div><div class="callout"><b>공유를 생략할 때</b><br>학습자가 위 네 질문에 한 줄씩 답하는 개인 점검표로 대체할 수 있습니다.</div>`}
];

courseSteps.lesson4=[
 {time:'5분',title:'최종 보고서 만들기',body:`<div class="lesson-two-lead"><span class="tag">AI CAPSTONE</span><h2>보고서는 AI 활용 능력을 한 번에 확인하는 종합과제입니다</h2><p>자료 이해·질문·구조화·생성·비판·수정을 모두 사용합니다.</p></div>`},
 {time:'8분',title:'AI가 먼저 질문하기',body:`<div class="callout"><b>이 문장은 ‘질문 유도 프롬프트’의 예시입니다.</b><br>정보가 부족한 상태에서 AI가 임의로 보고서를 쓰지 않고, 먼저 사용자에게 확인 질문을 하도록 만드는 방법입니다.</div><div class="review-materials"><section><span class="tag">실습용 원자료</span><h3>9월 25일 위생점검 기록</h3><p>14시 포장구역 점검 중 세척도구 1개가 작업대 하단에서 발견됐다. 해당 도구는 즉시 회수해 세척·소독한 뒤 지정 보관함으로 옮겼다. 작업자 6명에게 보관 기준을 다시 안내했으며 9월 26일 재점검 예정이다. 발생 원인과 최초 이탈 시점은 확인되지 않았다.</p></section><section><span class="tag">이 자료에서 일부러 비워 둔 정보</span><h3>AI가 질문해야 할 부분</h3><ul class="spacious"><li>보고서를 제출할 대상</li><li>보고서를 통해 결정받을 사항</li><li>후속조치의 담당자와 확정 기한</li></ul></section></div><span class="tag">원자료 포함 질문 유도 프롬프트</span><div class="prompt-box good">아래 원자료를 바탕으로 보고서를 작성하려고 합니다. 보고서를 바로 쓰지 말고, 보고 목적·주요 독자·원자료에서 빠진 핵심 정보 중 결과에 가장 큰 영향을 주는 내용을 먼저 최대 3개 질문하세요. 내가 답한 뒤에만 보고서 초안을 작성하고, 끝까지 확인되지 않은 내용은 [확인 필요]로 표시하세요.\n\n[원자료]\n9월 25일 14시 포장구역 점검 중 세척도구 1개가 작업대 하단에서 발견됐다. 해당 도구는 즉시 회수해 세척·소독한 뒤 지정 보관함으로 옮겼다. 작업자 6명에게 보관 기준을 다시 안내했으며 9월 26일 재점검 예정이다. 발생 원인과 최초 이탈 시점은 확인되지 않았다.</div><button class="button secondary copy-module-text" data-copy="아래 원자료를 바탕으로 보고서를 작성하려고 합니다. 보고서를 바로 쓰지 말고, 보고 목적·주요 독자·원자료에서 빠진 핵심 정보 중 결과에 가장 큰 영향을 주는 내용을 먼저 최대 3개 질문하세요. 내가 답한 뒤에만 보고서 초안을 작성하고, 끝까지 확인되지 않은 내용은 [확인 필요]로 표시하세요.\n\n[원자료]\n9월 25일 14시 포장구역 점검 중 세척도구 1개가 작업대 하단에서 발견됐다. 해당 도구는 즉시 회수해 세척·소독한 뒤 지정 보관함으로 옮겼다. 작업자 6명에게 보관 기준을 다시 안내했으며 9월 26일 재점검 예정이다. 발생 원인과 최초 이탈 시점은 확인되지 않았다.">원자료 포함 프롬프트 복사</button><div class="compare"><section><span class="tag">AI가 물을 수 있는 질문 예시</span><ul class="spacious"><li>이 보고서는 누구에게 제출하나요?</li><li>독자가 이 보고서를 보고 결정해야 할 사항은 무엇인가요?</li><li>원자료에 없는 담당자·기한은 추가 확인이 가능한가요?</li></ul></section><section><span class="tag">사용 방법</span><p>복사 버튼을 누르면 질문 유도 지시문과 실습용 원자료가 함께 복사됩니다. Gemini에 한 번에 붙여 넣고, AI가 먼저 묻는 질문에 답한 뒤 초안을 작성하게 합니다.</p></section></div>`},
 {time:'10분',title:'10분 초안 시연',body:`<div class="callout"><b>초안이 만들어지는 과정을 관찰합니다.</b><br>아래 원자료를 바탕으로 작성 조건을 정리하고, Gemini에서 초안을 만든 뒤 원자료와 대조하는 과정을 살펴봅니다. 잠시 후 같은 순서로 직접 실습합니다.</div><div class="timed-activity"><div><b>1</b><span>목적·독자 정하기</span></div><div><b>2</b><span>원자료·결과 형식 입력</span></div><div><b>3</b><span>프롬프트로 AI 초안 생성</span></div><div><b>4</b><span>원자료와 대조·수정</span></div></div><div class="review-materials"><section><span class="tag">실습 원자료</span><h3>9월 25일 위생점검 기록</h3><p>14시 포장구역 점검 중 세척도구 1개가 작업대 하단에서 발견됐다. 해당 도구는 즉시 회수해 세척·소독한 뒤 지정 보관함으로 옮겼다. 작업자 6명에게 보관 기준을 다시 안내했으며 9월 26일 재점검 예정이다. 발생 원인과 최초 이탈 시점은 확인되지 않았다.</p></section><section><span class="tag">입력 조건</span><h3>작성기에 이렇게 입력합니다</h3><ul class="spacious"><li><b>목적:</b> 위생점검 결과와 후속조치 보고</li><li><b>독자:</b> 생산관리 책임자</li><li><b>형식:</b> 핵심 사실·즉시 조치·예정 조치·확인 필요사항</li><li><b>검토:</b> 원자료에 없는 원인·판단은 [확인 필요] 표시</li></ul></section></div><div class="facilitator"><b>관찰할 핵심</b><span>작성기는 보고서를 자동으로 완성하는 도구가 아니라, AI에 전달할 요청을 빠짐없이 정리하는 도구입니다. 초안이 만들어지면 ‘관리 소홀’처럼 원자료에 없는 원인이 추가되지 않았는지 직접 찾아봅니다.</span></div><div class="actions"><button class="button orange" data-route="builder">보고서 작성기 살펴보기</button></div>`},
 {time:'12분',title:'원자료와 방금 나온 초안 비교시키기',body:`<div class="lesson-two-lead"><span class="tag">같은 GEMINI 대화창에서 계속</span><h2>원자료와 방금 생성된 초안을 AI에게 비교시킵니다</h2><p>맞습니다. 아래 프롬프트는 <b>작성기에 넣었던 원자료</b>와 <b>Gemini가 방금 만든 보고서 초안</b>을 서로 대조해 오류와 누락을 찾으라는 요청입니다.</p></div><div class="practice-flow"><span><b>1</b> 작성기 프롬프트 입력</span><span><b>2</b> Gemini 초안 생성</span><span><b>3</b> 원자료·초안 비교 프롬프트 입력</span><span><b>4</b> 진단 확인 후 수정 요청</span></div><div class="peer-review"><div><b>근거</b><p>없는 내용은?</p></div><div><b>누락</b><p>빠진 사실은?</p></div><div><b>독자</b><p>추가 질문은?</p></div><div><b>행동</b><p>다음 조치는?</p></div></div><div class="callout"><b>어디에 넣나요?</b><br>초안을 만든 <b>같은 Gemini 대화창</b>에 아래 프롬프트만 이어서 붙여 넣으세요. 원자료와 초안이 이미 그 대화창에 있으므로 다시 복사할 필요가 없습니다. 새 대화창이라면 원자료와 초안도 함께 붙여 넣어야 합니다.</div><button class="button secondary prompt-preview-trigger" data-reveal="self-critique-prompt" data-open-label="원자료·초안 비교 프롬프트 보기" data-close-label="비교 프롬프트 닫기" aria-expanded="false">원자료·초안 비교 프롬프트 보기</button><section id="self-critique-prompt" class="full-prompt-panel" hidden><div class="prompt-box good">방금 작성한 보고서 초안을 바로 수정하지 말고, 처음 제공한 원자료와 대조해 가장 취약한 점부터 진단해줘.\n\n① 원자료에서 확인되지 않는 문장\n② 초안에서 빠진 사실\n③ 독자가 추가로 물을 질문\n④ 다음 조치로 보이지만 아직 확정되지 않은 내용\n\n위 네 항목으로 나눠 표로 제시하고, 각 판단의 근거를 원자료의 어떤 내용과 대조했는지 함께 적어줘. 원자료에 없는 내용을 새로 추측하지 말고, 확인할 수 없는 것은 [확인 필요]로 표시해줘. 아직 수정본은 작성하지 마.</div><button class="button orange copy-module-text" data-copy="방금 작성한 보고서 초안을 바로 수정하지 말고, 처음 제공한 원자료와 대조해 가장 취약한 점부터 진단해줘.\n\n① 원자료에서 확인되지 않는 문장\n② 초안에서 빠진 사실\n③ 독자가 추가로 물을 질문\n④ 다음 조치로 보이지만 아직 확정되지 않은 내용\n\n위 네 항목으로 나눠 표로 제시하고, 각 판단의 근거를 원자료의 어떤 내용과 대조했는지 함께 적어줘. 원자료에 없는 내용을 새로 추측하지 말고, 확인할 수 없는 것은 [확인 필요]로 표시해줘. 아직 수정본은 작성하지 마.">원자료·초안 비교 프롬프트 복사</button></section><div class="callout" style="margin-top:16px"><b>진단을 확인한 다음</b><br>틀린 진단은 사람이 바로잡고, “확인된 진단만 반영해 수정본을 작성해줘”라고 이어서 요청합니다.</div>`},
 {time:'15분',title:'개인 10분 실습',body:`<div class="actions"><button class="button orange" data-route="challenge">10분 타이머 시작</button><button class="button secondary" data-route="builder">작성기 열기</button></div><div class="facilitator"><b>성공 기준</b><span>AI와 두 번 이상 대화하고 근거 없는 내용을 한 개 이상 찾아 수정합니다.</span></div>`},
 {time:'5분',title:'결과보다 과정 공유',body:`<div class="presentation-guide"><h2>AI 협업 과정을 공유합니다</h2><ol><li>첫 질문을 어떻게 바꿨는가?</li><li>AI가 무엇을 되물었는가?</li><li>어떤 오류를 사람이 발견했는가?</li><li>시간이 어디서 줄었는가?</li></ol></div>`}
];

